    var amex = new RegExp("^3[47][0-9]{13}$");
    var mastercard = new RegExp("^5[1-5][0-9]{14}$");
    var discover = new RegExp("^65[4-9][0-9]{13}|64[4-9][0-9]{13}|6011[0-9]{12}|(622(?:12[6-9]|1[3-9][0-9]|[2-8][0-9][0-9]|9[01][0-9]|92[0-5])[0-9]{10})$");
